package com.aicharacter.v3;
import org.json.JSONObject;
/** Whole-body mechanics shared by human/cat. Support and COM determine balance under gravity. */
public final class PhysicsBodyState{
 public double massKg=50,velocityX,velocityY,centerOfMassX,centerOfMassY=.55,groundClearanceM,groundReaction,traction=1,balance=1,supportLeft=-.18,supportRight=.18,landingInstability;public boolean grounded=true,falling=false;public long lastUpdatedAt;
 public JSONObject toJson(){JSONObject j=new JSONObject();try{j.put("massKg",massKg);j.put("velocityX",velocityX);j.put("velocityY",velocityY);j.put("centerOfMassX",centerOfMassX);j.put("centerOfMassY",centerOfMassY);j.put("groundClearanceM",groundClearanceM);j.put("groundReaction",groundReaction);j.put("traction",traction);j.put("balance",balance);j.put("supportLeft",supportLeft);j.put("supportRight",supportRight);j.put("landingInstability",landingInstability);j.put("grounded",grounded);j.put("falling",falling);j.put("lastUpdatedAt",lastUpdatedAt);}catch(Exception ignored){}return j;}
 public static PhysicsBodyState fromJson(JSONObject j,double mass){PhysicsBodyState p=new PhysicsBodyState();p.massKg=mass;if(j==null)return p;p.massKg=Math.max(.5,j.optDouble("massKg",mass));p.velocityX=j.optDouble("velocityX");p.velocityY=j.optDouble("velocityY");p.centerOfMassX=j.optDouble("centerOfMassX");double defaultCom=mass<10?.24:.55;p.centerOfMassY=j.optDouble("centerOfMassY",defaultCom);p.groundClearanceM=Math.max(0,j.optDouble("groundClearanceM",0));p.groundReaction=Math.max(0,j.optDouble("groundReaction"));p.traction=Math.max(.05,Math.min(1,j.optDouble("traction",1)));p.balance=Math.max(0,Math.min(1,j.optDouble("balance",1)));p.supportLeft=j.optDouble("supportLeft",-.18);p.supportRight=j.optDouble("supportRight",.18);p.landingInstability=Math.max(0,Math.min(1,j.optDouble("landingInstability",0)));p.grounded=j.optBoolean("grounded",true);p.falling=j.optBoolean("falling",false);p.lastUpdatedAt=j.optLong("lastUpdatedAt");return p;}
}